import math
def priority(task, state, b=0.5, m=4.0, k=0.7, qthresh=0.6):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    load = state.queue_work / max(state.capacity, 1e-6)
    # under heavy load, prioritize urgency/slack; under light load, WSPT+aging
    if load > qthresh:
        urgency = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
        return urgency * (1.0 + b * wait / est)
    return tier * task.weight / est * (1.0 + b * wait / est)

import math
def priority(task, state, b=0.5, m=3.0, k=0.5, prem_ratio=2.0, conv_ratio=1.0):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - est - state.now
    # premium: hard urgency based on slack vs est; standard: response-time oriented
    if task.tenant == 'premium':
        if slack < 0:
            return 1e6 + 1.0 / est
        urgency = task.weight / est * math.exp(-max(0.0, slack) / (k * mean_est))
        return m * urgency + prem_ratio * task.weight / est * (1.0 + b * wait / est)
    # standard: favor short jobs with aging, gently boosted by due if present
    base = task.weight / est * (1.0 + b * wait / est)
    due_bonus = 0.0
    if task.due > 0:
        due_bonus = math.exp(-max(0.0, slack) / (k * mean_est))
    return conv_ratio * base * (1.0 + 0.2 * due_bonus)

import math
def priority(task, state, b=0.5, m=3.0, k=0.5, load_hi=0.6, load_lo=0.25):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - est - state.now
    tier = m if task.tenant == 'premium' else 1.0
    load = state.queue_work / max(state.capacity, 1e-6)
    if task.tenant == 'premium' and slack < 0:
        return 1e6
    atc = tier * task.weight / est * math.exp(-max(0.0, slack) / (k * mean_est))
    aged = task.weight / est * (1.0 + b * wait / est)
    if load > load_hi:
        # heavy load: strict urgency for premium, aging for standard
        if task.tenant == 'premium':
            return atc * (1.0 + 0.5 * wait / est)
        return aged
    elif load < load_lo:
        # light load: clear small jobs fast, premium first
        return tier * task.weight / est
    else:
        return 0.6 * atc + 0.4 * aged

import math
def priority(task, state, m=3.0, k=0.5, b=0.5, wait_boost=1.0, prem_slack_ratio=1.0):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - est - state.now
    # premium: strong protection with escalating urgency as slack shrinks
    if task.tenant == 'premium':
        if slack < 0:
            return 1e6 + 1.0 / est
        ratio = slack / est
        if ratio < prem_slack_ratio:
            return m * 1e5 + task.weight / est
        return m * task.weight / est * math.exp(-max(0.0, slack) / (k * mean_est)) * (1.0 + b * wait / est)
    # standard: aging WSPT, but avoid starving long jobs by capping aging boost
    aged = task.weight / est * (1.0 + b * min(wait, wait_boost * mean_est) / est)
    # slight due-awareness for standard if due is set in future
    if task.due > 0 and slack > 0:
        aged *= 1.0 + 0.3 * math.exp(-slack / (k * mean_est))
    return aged

import math
def priority(task, state, m=4.0, k=0.5, b=0.6, hard=1e6, prem_slack_frac=0.5, conv_cap=4.0):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - est - state.now
    if task.tenant == 'premium':
        if slack < 0:
            return hard + task.weight / est
        if slack < prem_slack_frac * est:
            return hard * 0.5 + m * task.weight / est
        urgency = m * task.weight / est * math.exp(-slack / (k * mean_est))
        return urgency * (1.0 + b * wait / est)
    # standard: WSPT with capped aging to bound p90 tail
    age = 1.0 + b * min(wait / est, conv_cap)
    return task.weight / est * age

