            return hard + 1.0 / est
        ratio = slack / est
        if ratio < prem_ratio:
            return hard * 0.25 + m * task.weight / est
        return m * task.weight / est * math.exp(-slack / (k * mean_est))
    # standard: pure WSPT with capped aging; due ignored to protect p90
    age = 1.0 + b * min(wait / est, conv_aging_cap)
    return task.weight / est * age

import math
def priority(task, state, m=3.0, k=0.5, b=0.7, hard=1e6, load_lo=0.25, load_hi=0.65, conv_short=0.8):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - est - state.now
    load = state.queue_work / max(state.capacity, 1e-6)
    if task.tenant == 'premium':
        if slack < 0:
            return hard
        atc = m * task.weight / est * math.exp(-max(0.0, slack) / (k * mean_est))
        return atc * (1.0 + b * wait / est)
    # standard: light load favors shortest; heavy favors aging to avoid starvation
    if load < load_lo:
        return task.weight / est * (1.0 + conv_short / math.sqrt(est))
    age = 1.0 + b * wait / est
    base = task.weight / est * age
    if load > load_hi:
        base *= 1.0 / math.sqrt(est)
    return base

