    util = state.queue_work / max(state.capacity, 1e-6)
    if task.tenant == 'premium':
        slack = task.due - state.now - est
        # ATC urgency with load-aware scaling: under load, weight slack more
        scale = k * max(state.mean_est, 1e-6) * (1.0 + util)
        urg = task.weight / est * math.exp(-max(slack, 0.0) / scale)
        return guard + m * urg * (1.0 + r * ratio)
