def priority(task, state, k=2.0, m=4.0, c=2.5, p=0.5, w=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    # premium: pure EDF-style urgency, ignore size to avoid delaying hard deadlines
    if task.tenant == 'premium':
        slack = task.due - est - state.now
        urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
        return tier * task.weight * urgency * (1.0 + w * wait / est)
    # standard: SJF with aging for p90 response time
    aging = 1.0 + w * wait / est
    return task.weight * aging / (est ** p)

