def priority(task, state, c=1.0, m=6.0, q=0.5):
    # WaitGuard for premium, SPT-biased aging for standard; switches under load
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    load = state.queue_work / max(state.capacity, 1e-6)
    if task.tenant == 'premium':
        slack = max(0.0, task.due - est - state.now)
        base = m / est * math.exp(-slack / (q * max(state.mean_est, 1e-6)))
        return base + (1e6 if ratio >= c else 0.0)
    # standard: aging SPT, boosted when queue is heavy to cut tail
    return (1.0 / est) * (1.0 + ratio) * (1.0 + load)

def priority(task, state, c=1.0, m=3.0, k=1.0):
    # Premium: slack-based EDF-ish urgency; standard: wait-guard + aging WSPT
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    if task.tenant == 'premium':
        slack = task.due - est - state.now
        # prioritize tight slack, with aging to avoid starvation
        return m * (-slack) / est + (1e6 if ratio >= c else 0.0) + wait / est
    return task.weight / est * (1.0 + k * wait / est) + (1e6 if ratio >= c else 0.0)

def priority(task, state, c=1.0, m=4.0, k=0.5, hi=0.7):
    # Load-adaptive: under heavy load prioritize premium hard-deadline + standard tail
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    load = state.queue_work / max(state.capacity, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    if task.tenant == 'premium':
        urgency = m * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
        return urgency + (1e6 if ratio >= c else 0.0)
    if load >= hi:
        # heavy: SPT with aging to protect p90
        return (1.0 / est) * (1.0 + ratio) + (1e6 if ratio >= c else 0.0)
    # light: aging WSPT
    return task.weight / est * (1.0 + ratio) + (1e6 if ratio >= c else 0.0)

def priority(task, state, m=4.0, k=0.5, c=1.0, hi=0.6, lo=0.25):
    import math
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    load = state.queue_work / max(state.capacity, 1e-6)
    if task.tenant == 'premium':
        slack = task.due - est - state.now
        if slack <= 0:
            return 1e7 * (1.0 + ratio)
        urgency = m * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
        # under heavy load, premium gets extra protection
        boost = 1.0 + (2.0 if load >= hi else 0.0)
        return urgency * boost + (1e6 if ratio >= c else 0.0)
    if load >= hi:
        # heavy: pure SPT with mild aging for p90 tail
        return (1.0 / est) * (1.0 + 0.5 * ratio)
    if load <= lo:
        # light: aging WSPT
        return task.weight / est * (1.0 + ratio)
    # mid: blend
    return (task.weight / est) * (1.0 + ratio) * 0.5 + (1.0 / est) * (1.0 + ratio) * 0.5

