    if load >= hi:
        return (1.0 / est) * (1.0 + ratio) * (1.0 + s * load)
    return task.weight / est * (1.0 + ratio)

import math
def priority(task, state, m=4.0, k=0.5, c=1.0, g=1.0, h=0.5):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    mean_est = max(state.mean_est, 1e-6)
    if task.tenant == 'premium':
        slack = task.due - est - state.now
        if slack <= 0:
            return 1e8 + h * ratio
        urgency = m * task.weight / est * math.exp(-slack / (k * mean_est))
        lin = g * (-slack) / est
        return urgency + lin + (1e6 if ratio >= c else 0.0)
    age = math.exp(g * ratio / mean_est)
    return task.weight / est * age + (1.0 / est) * (1.0 + h * ratio)

