def priority(task, state, k=1.5, m=3.0, qthresh=8.0):
    # ATC but reshape slack: use due-now (not due-est) so long jobs aren't over-penalized,
    # and switch to pure EDF-ish urgency when queue is short.
    if state.queue_len <= qthresh:
        return -task.due
    slack = max(0.0, task.due - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))

def priority(task, state, m=3.0, b=1.0, c=2.5):
    # Premium: EDF-like due urgency with aging guard; Standard: aging WSPT.
    wait = state.now - task.release
    if task.tenant == 'premium':
        ratio = wait / max(task.estimated_runtime, 1e-6)
        guard = 1e6 if ratio >= c else 0.0
        return guard + m * b * wait - task.due
    return task.weight / max(task.estimated_runtime, 1e-6) * (1.0 + b * wait / max(task.estimated_runtime, 1e-6))

