def priority(task, state, m=5.0, k=1.0, c=2.5, b=1.0):
    # Premium: EDF with urgency boost when slack tight; Standard: aging WSPT with guard.
    wait = state.now - task.release
    if task.tenant == 'premium':
        slack = task.due - task.estimated_runtime - state.now
        near_due = m if slack < task.estimated_runtime else 1.0
        return near_due * (task.weight / max(task.estimated_runtime, 1e-6)) - slack / max(k * state.mean_est, 1e-6)
    ratio = wait / max(task.estimated_runtime, 1e-6)
    guard = 1e6 if ratio >= c else 0.0
    return guard + task.weight / max(task.estimated_runtime, 1e-6) * (1.0 + b * ratio)
